const EARTH_RADIUS = 6371000;

function degreesToRadians(degrees) {
    return degrees * (Math.PI / 180);
}

function radiansToDegrees(radians) {
    return radians * (180 / Math.PI);
}

function angularDistance(location1, location2) {
    const location1_latitude_radians = degreesToRadians(location1.latitude);
    const location2_latitude_radians = degreesToRadians(location2.latitude);
    return Math.acos(
        Math.sin(location1_latitude_radians) * Math.sin(location2_latitude_radians) +
        Math.cos(location1_latitude_radians) * Math.cos(location2_latitude_radians) *
        Math.cos(degreesToRadians(Math.abs(location1.longitude - location2.longitude)))
    );
}

function circleDistance(location1, location2) {
    return EARTH_RADIUS * angularDistance(location1, location2);
}

function constrain(value, min, max) {
    if (value < min) return min;
    if (value > max) return max;
    return value;
}

// --------------------------------------------------------------------
// Data process
// --------------------------------------------------------------------

var new_payload = [];

function ftdProcess(bytes, port, sequence_id, gateways) {

    // Filter wrong messages by length
    if ((1 == port) && (bytes.length != 10)) {
        node.warn("Wrong length for fPort 1 " + bytes.length);
        return null;
    }
    if ((11 == port) && (bytes.length != 11)) {
        node.warn("Wrong length for fPort 11 " + bytes.length);
        return null;
    }

    const messages = new Array(gateways.length);

    // decode bytes    
    var lonSign = (bytes[0] >> 7) & 0x01 ? -1 : 1;
    var latSign = (bytes[0] >> 6) & 0x01 ? -1 : 1;
    var encLat = ((bytes[0] & 0x3f) << 17) + (bytes[1] << 9) + (bytes[2] << 1) + (bytes[3] >> 7);
    var encLon = ((bytes[3] & 0x7f) << 16) + (bytes[4] << 8) + bytes[5];
    var hdop = bytes[8] / 10;
    var sats = bytes[9];

    // send only acceptable quality of position to mappers
    if ((hdop > 2) || (sats < 5)) {
        // node.warn("hdop " + hdop + " sats " + sats);
        // return null; // Accept locations with a lower quality
    }

    var data = {};

    data.latitude = latSign * (encLat * 108 + 53) / 10000000;
    data.longitude = lonSign * (encLon * 215 + 107) / 10000000;

    // build gateway data
    data.num_gateways = gateways.length;

    data.min_distance = 1e6;
    data.max_distance = 0;
    data.min_rssi = 200;
    data.max_rssi = -200;
    data.min_snr = 200;
    data.max_snr = -200;
    var gateway_num = 0;
    var gw_id = "";
    var gw_colors = ["yellow", "lime", "red", "teal", "navy", "fuchsia", "green", "purple", "darkblue", "orange"];

    gateways.forEach(function (gateway) {
        node.log("dr" + gateway.dr);
        gw_id = gateway.gatewayId;
        if (gateway.rssi < data.min_rssi) data.min_rssi = gateway.rssi;
        if (gateway.rssi > data.max_rssi) data.max_rssi = gateway.rssi;
        if (gateway.snr < data.min_snr) data.min_snr = gateway.snr;
        if (gateway.snr > data.max_snr) data.max_snr = gateway.snr;
        if (gateway.location) {
            var distance = parseInt(circleDistance(data, gateway.location));
            if (distance < data.min_distance) data.min_distance = distance;
            if (distance > data.max_distance) data.max_distance = distance;

            // Push gateway location to the world map
            new_payload.push({ payload: { name: gw_id, lat: gateway.location.latitude, lon: gateway.location.longitude, iconColor: gw_colors[gateway_num], label: gw_id, icon: "cloud-upload", Distance: (distance.toString() + "m") } });
            // node.warn("Pushed " + gw_id + " numGW = " + gateway_num + " Color " + gw_colors[gateway_num]);
            messages[gateway_num + 1] = new_payload;
            new_payload = [];
            gateway_num++;
        }

    });

    // Push tester location to the world map
    if ((data.latitude < 0.00001) && (data.longitude < 0.0001)) {
        // No tester location
        new_payload.push({ payload: { name: "Tester-" + msg.payload.deviceInfo.devEui, lat: data.latitude, lon: data.longitude, iconColor: "blue", label: "Tester-" + msg.payload.deviceInfo.devEui, icon: "rss", HDOP: hdop, Satellites: sats, Gateways: data.num_gateways, Min_RSSI: data.min_rssi, Max_RSSI: data.max_rssi, Min_SNR: data.min_snr, Max_SNR: data.max_snr, deleted: true } });
    } else {
        new_payload.push({ payload: { name: "Tester-" + msg.payload.deviceInfo.devEui, lat: data.latitude, lon: data.longitude, iconColor: "blue", label: "Tester-" + msg.payload.deviceInfo.devEui, icon: "rss", HDOP: hdop, Satellites: sats, Gateways: data.num_gateways, Min_RSSI: data.min_rssi, Max_RSSI: data.max_rssi, Min_SNR: data.min_snr, Max_SNR: data.max_snr } });
    }
    messages[0] = new_payload;
    new_payload = [];

    return messages;
}

